export function EmptyState({
  heading = "{{heading}}",
  body = "{{body}}",
  accent = "{{accent}}",
  force = {{force}},
}) {
  const items = ["Marketing site redesign", "Q3 roadmap", "Onboarding revamp"];
  return (
    <div style={{ width: 280, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, textAlign: "center" }}>
      {force ? (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8, padding: "14px 8px", color: accent }}>
          <svg width="32" height="32" viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="7" width="16" height="13" rx="2" fill="none" stroke="currentColor" strokeWidth="1.6" /><path d="M4 10h16M9 4h6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" /></svg>
          <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700, color: "#241430" }}>{heading}</h3>
          <p style={{ margin: 0, fontSize: 12, color: "#241430aa", maxWidth: 200 }}>{body}</p>
        </div>
      ) : (
        <ul style={{ listStyle: "none", margin: 0, padding: 0, textAlign: "left" }}>
          {items.map((item) => (
            <li key={item} style={{ padding: "9px 10px", borderBottom: "1px solid #24143014", fontWeight: 600, fontSize: 13 }}>{item}</li>
          ))}
        </ul>
      )}
    </div>
  );
}
